// PROOF OF CONCEPT — album data is baked in at build time (see albumPhotos.js,
// generated by scripts/fetch-photos.sh). Future version: store album links in a
// database, manageable through an admin portal, and render from there instead.
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import AccordionGallery from '../components/AccordionGallery.jsx'
import { ALBUMS } from './albumPhotos.js'

const thumb = (src) => src.replace('=w1200', '=w800')
const SETTLE_MS = 280 // hover linistit atat => gridul revine; miscari rapide tin gridul stins
const REVEAL_MS = 280

function MasonryPhoto({ src, alt, href }) {
  const imgRef = useRef(null)
  const [ready, setReady] = useState(false)
  const [bone, setBone] = useState(true)

  useLayoutEffect(() => {
    const img = imgRef.current
    if (img?.complete && img.naturalWidth > 0) setReady(true)
  }, [src])

  useEffect(() => {
    if (!ready) return undefined
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setBone(false)
      return undefined
    }
    const id = window.setTimeout(() => setBone(false), REVEAL_MS)
    return () => window.clearTimeout(id)
  }, [ready])

  return (
    <figure className={ready ? 'is-ready' : undefined} aria-busy={ready ? undefined : true}>
      <a href={href} target="_blank" rel="noreferrer">
        {bone ? <span className="skeleton masonry-skeleton" aria-hidden="true" /> : null}
        <img
          ref={imgRef}
          src={src}
          alt={alt}
          loading="lazy"
          decoding="async"
          referrerPolicy="no-referrer"
          onLoad={() => setReady(true)}
          onError={() => setReady(true)}
        />
      </a>
    </figure>
  )
}

export default function Evenimente() {
  const [added, setAdded] = useState([])
  // null = all events; otherwise index into albums with photos
  const [open, setOpen] = useState(null)
  // albumul randat efectiv + stare fade; la hover rapid, shown se comite
  // doar dupa SETTLE_MS de liniste, deci gridul ramane stins intre switchuri
  const [shown, setShown] = useState(null)
  const [faded, setFaded] = useState(false)
  const prevOpen = useRef(open)
  const timer = useRef(null)

  useEffect(() => {
    if (prevOpen.current === open) return
    prevOpen.current = open
    setFaded(true)
    timer.current = setTimeout(() => {
      setShown(open)
      setFaded(false)
    }, SETTLE_MS)
    return () => clearTimeout(timer.current)
  }, [open ])

  useEffect(() => () => clearTimeout(timer.current), [])

  useEffect(() => {
    let cancelled = false
    fetch('/api/albums')
      .then((response) => (response.ok ? response.json() : { albums: [] }))
      .then((data) => {
        if (!cancelled) setAdded(data.albums || [])
      })
      .catch(() => {})
    return () => {
      cancelled = true
    }
  }, [])

  const albums = useMemo(() => {
    const seen = new Set()
    const merged = []
    for (const album of [...added, ...ALBUMS]) {
      if (!album.href || seen.has(album.href)) continue
      seen.add(album.href)
      merged.push(album)
    }
    return merged
  }, [added])

  const withPhotos = albums.filter((a) => a.photos.length > 0)
  const sections = shown === null ? albums : [withPhotos[shown]]

  return (
    <main className="page">
      <header className="hero">
        <h1>evenimente</h1>
        <p className="lede">
          Conferințe de deschidere și albume foto din fiecare an —
          click pe un eveniment pentru fotografiile lui.
        </p>
      </header>

      <section className="flush">
        <AccordionGallery
          items={withPhotos.map((a) => ({
            image: thumb(a.photos[0]),
            label: a.title,
            alt: a.title,
          }))}
          trigger="hover"
          accentColor="#f4f0f0"
          textColor="#f4f0f0"
          overlayColor="#000000"
          height={380}
          onSelect={setOpen}
        />
      </section>

      <div className={'grid-fade' + (faded ? ' is-out' : '')}>
      {sections.map((a) => (
        <section key={a.href}>
          <div className="masonry">
            {a.photos.map((src, i) => (
              <MasonryPhoto
                key={src}
                src={src}
                href={a.href}
                alt={`${a.title} — fotografia ${i + 1}`}
              />
            ))}
          </div>
          <p>
            <small>
              {a.meta} —{' '}
              <a href={a.href} target="_blank" rel="noreferrer">
                albumul complet în google photos
              </a>
            </small>
          </p>
        </section>
      ))}
      </div>
    </main>
  )
}
